list-partial[enumerate](
    %通常将 #0表达式根据 #1记作形如 #2 的表达式。%(Type.Expr-UTLC.lambda, deBruijnIndex ,Type.lambda(@x, P(x)),),
    %将形如 #0 的多元函数记作 #1%(
        Type.lambda(
            @x,
            Type.lambda(@y, Type.apply(P(x), y))
        ),
        Type.lambda(list-partial[none](@x, @y), Type.apply(P(x), y))
    )
)
